import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        final int N = sc.nextInt();
        int[] Qn = new int[N];
        int[] An = new int[N];
        int[] Bn = new int[N];

        for (int i = 0; i < N; i++) {
            Qn[i] = sc.nextInt();
        }
        for (int i = 0; i < N; i++) {
            An[i] = sc.nextInt();
        }
        for (int i = 0; i < N; i++) {
            Bn[i] = sc.nextInt();
        }

        int maxServings = 0;

        for (int aServings = 0; aServings <= 1000000; aServings++) {
            boolean canMakeA = true;
            int[] remainingIngredients = new int[N];

            for (int i = 0; i < N; i++) {
                remainingIngredients[i] = Qn[i] - aServings * An[i];
                if (remainingIngredients[i] < 0) {
                    canMakeA = false;
                    break;
                }
            }

            if (!canMakeA) {
                break;
            }

            int bServings = Integer.MAX_VALUE;

            for (int i = 0; i < N; i++) {
                if (Bn[i] > 0) {
                    bServings = Math.min(bServings, remainingIngredients[i] / Bn[i]);
                }
            }

            maxServings = Math.max(maxServings, aServings + bServings);
        }

        System.out.println(maxServings);
    }
}
